/* ---- Ticket identity badge: message balloon on the app primary color ---- */
export function TicketBadge({ size = 34 }: { size?: number }) {
  return (
    <span className="ck-badge" style={{ width: size, height: size }}>
      {Icon.chat({ style: { width: size * 0.56, height: size * 0.56 } })}
    </span>
  );
}

/* ---- inline rich text: **negrito** e _link_ ---- */
export function renderRich(text: string): ReactNode[] {
  const out: ReactNode[] = [];
  const re = /(\*\*[^*]+\*\*|_[^_]+_)/g;
  let last = 0, m: RegExpExecArray | null, key = 0;
  while ((m = re.exec(text))) {
    if (m.index > last) out.push(text.slice(last, m.index));
    const tok = m[0];
    if (tok.startsWith("**")) out.push(<strong key={key++}>{tok.slice(2, -2)}</strong>);
    else out.push(<button key={key++} type="button" className="ck-link">{tok.slice(1, -1)}</button>);
    last = m.index + tok.length;
  }
  if (last < text.length) out.push(text.slice(last));
  return out;
}

/* ---- Cria um novo chamado (modelo unificado) com o histórico inicial.
   `protocolo` é calculado por quem chama (App), a partir da lista atual. ---- */
export function createChamado(target: HelpTarget, userMessage: string, userName: string, protocolo: string): Chamado {
  const kindLabel = target.kind === "audio" ? "Áudio" : "Lote";
  const now = Date.now();
  const firstName = userName.split(/\s+/)[0] || userName;
  const messages: ChamadoMessage[] = [
    { id: "m1", role: "cliente", author: userName, body: userMessage.trim(), time: "Agora", ts: now },
    {
      id: "m2", role: "suporte", author: "Equipe Fuzzr", time: "Agora", ts: now + 1,
      body: `Olá ${firstName}, tudo bem? Recebemos sua solicitação por aqui. Iremos trabalhar no seu ${kindLabel} e avisaremos quando ficar pronto.`,
    },
    {
      id: "m3", role: "suporte", author: "Equipe Fuzzr", time: "Agora", ts: now + 2,
      body: "Você pode retornar aqui _usando este link_ ou pelo menu principal, opção **Chamados**. Ajudamos com mais alguma coisa?",
      options: [
        { label: "Opções de Auto-ajuda", reply: "Boa! Você pode acessar a Documentação, FAQ e Tutoriais do Ampli _clicando aqui_." },
        { label: "Não, obrigado!", reply: "Ok, então! Fique à vontade para fechar esta janela. Até já!" },
      ],
    },
  ];
  return {
    id: "ch" + now,
    protocolo,
    subject: `Ajuda com o ${kindLabel} ${target.title}`,
    status: "aberto",
    priority: "media",
    category: kindLabel,
    requester: userName,
    target,
    createdTs: now,
    openedDate: "Hoje",
    updatedTs: now,
    date: "Agora",
    messages,
  };
}

/* ============================================================
   Modal — Abrir chamado
   ============================================================ */
export function HelpTicketModal({ target, onClose, onSubmit }: {
  target: HelpTarget; onClose: () => void; onSubmit: (text: string) => void;
}) {
  const kindLabel = target.kind === "audio" ? "Áudio" : "Lote";
  const [text, setText] = useState(`Olá, preciso de ajuda com o ${kindLabel} ${target.title}`);
  const submit = () => { if (text.trim()) onSubmit(text.trim()); };

  return (
    <div className="md-scrim ck-modal-scrim" onMouseDown={onClose}>
      <div className="md-box ck-modal anim-pop" onMouseDown={(e) => e.stopPropagation()}>
        <div className="md-head">
          <div>
            <div className="u-label">Preciso de Ajuda</div>
            <h2 className="md-title" style={{ paddingTop: 8 }}>Abrir chamado</h2>
            <p className="md-sub">{kindLabel} {target.title}</p>
          </div>
          <button className="icon-btn" onClick={onClose}>{Icon.close({ style: { width: 18, height: 18 } })}</button>
        </div>
        <div className="md-body">
          <textarea className="field ck-modal-textarea" value={text} autoFocus rows={4}
            onChange={(e) => setText(e.target.value)}
            onKeyDown={(e) => { if (e.key === "Enter" && (e.metaKey || e.ctrlKey)) submit(); }} />
          <div className="ck-modal-foot">
            <button className="btn btn-primary btn-lg" disabled={!text.trim()} onClick={submit}>
              Enviar {Icon.chat({ style: { width: 16, height: 16 } })}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

/* ============================================================
   Janela — Chat de Chamado (variação do Ampl.IA)
   ============================================================ */
export function ChamadoChat({ chamado, onClose, onChoose }: {
  chamado: Chamado; onClose: () => void; onChoose: (msgId: string, option: ChamadoOption) => void;
}) {
  const scrollRef = useRef<HTMLDivElement>(null);
  const kindLabel = chamado.target?.kind === "lote" ? "Lote" : "Áudio";

  useEffect(() => {
    const el = scrollRef.current;
    if (el) el.scrollTop = el.scrollHeight;
  }, [chamado.messages]);

  return (
    <div className="ai-win ck-win" role="dialog" aria-label={"Chamado " + chamado.protocolo}>
      <header className="ai-head ck-head">
        <div className="ai-head-id">
          <TicketBadge size={38} />
          <div className="ai-head-txt">
            <div className="ai-head-name">Fuzzr Help!</div>
            <div className="ai-head-status">Chamado {chamado.protocolo}</div>
          </div>
        </div>
        <div className="ai-head-actions">
          <button className="ai-iconbtn" title="Fechar" onClick={onClose}>
            {Icon.close({ style: { width: 18, height: 18 } })}
          </button>
        </div>
      </header>

      <div className="ai-body ck-body" ref={scrollRef}>
        {/* header do chat — rola junto com a conversa */}
        <div className="ck-hero">
          <AmpliHelpLogo height={30} />
          <h2 className="ck-hero-title">Ajuda com o {kindLabel}</h2>
          <p className="ck-hero-sub">{chamado.target?.title || chamado.subject}</p>
        </div>

        <div className="ck-divider"></div>
        <div className="ck-start">Início do chamado</div>

        <div className="ai-thread ck-thread">
          {chamado.messages.map((m) => (
            <div key={m.id}>
              <div className={"ai-msg " + (m.role === "cliente" ? "user" : "assistant")}>
                {m.role === "suporte" && <TicketBadge size={28} />}
                <div className="ai-bubble">{renderRich(m.body)}</div>
              </div>
              {m.options && m.options.length > 0 && (
                <div className="ck-options">
                  {m.options.map((o) => (
                    <button key={o.label} className="ck-opt" onClick={() => onChoose(m.id, o)}>
                      {o.label}
                    </button>
                  ))}
                </div>
              )}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}
